#include <bits/stdc++.h>
#include <tr1/unordered_map>
using namespace std;

inline void readInt(int &v) {
    char ch;
    v = 0;
    bool neg = false;
    while (!isdigit(ch = getchar())) {
        if (ch == '-') neg = true;
    }
    do {
        v = (v << 3) + (v << 1) + (ch ^ '0');
    } while (isdigit(ch = getchar()));
    if (neg) v = -v;
}

inline void readLL(long long &v) {
    char ch;
    v = 0;
    bool neg = false;
    while (!isdigit(ch = getchar())) {
        if (ch == '-') neg = true;
    }
    do {
        v = (v << 3) + (v << 1) + (ch ^ '0');
    } while (isdigit(ch = getchar()));
    if (neg) v = -v;
}

long long n, k, modVal;
int fact[262155];
int invFact[262155];

inline int modPow(int base, long long exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (long long)result * base % modVal;
        }
        base = (long long)base * base % modVal;
        exp >>= 1;
    }
    return result;
}

int dp[262155][31];
bool visited[262155][31];
int bitCount[262155];

inline int countTrailingZeros(int x) {
    int cnt = 0;
    while (x && (x & 1) == 0) {
        ++cnt;
        x >>= 1;
    }
    return cnt;
}

int twoPowerCount[262155];

inline int binomial(int n, int m) {
    return (long long)fact[n] * invFact[m] % modVal * invFact[n - m] % modVal;
}

inline int recursiveSolve(int n, int k) {
    if (n == 0) return 1;
    if (k == 0) return 0;
    if (dp[n][k] != -1) return dp[n][k];

    int step = 1 << bitCount[n];
    int res = 0;
    for (int i = n; i >= step; i -= 2) {
        res = ((long long)res + (long long)binomial(n, i) * recursiveSolve(n - i, k - 1) % modVal * k) % modVal;
    }
    return dp[n][k] = res;
}

vector<pair<int, int>> orderList;

inline int iterativeSolve(int startN, int startK) {
    queue<pair<int, int>> q;
    q.push({startN, startK});

    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        int curN = cur.first, curK = cur.second;
        orderList.push_back({curN, curK});

        if (curN == 0 || curK == 0) continue;

        int step = 1 << bitCount[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (twoPowerCount[i] + twoPowerCount[curN - i] == twoPowerCount[curN] && !visited[curN - i][curK - 1]) {
                visited[curN - i][curK - 1] = true;
                q.push({curN - i, curK - 1});
            }
        }
    }

    for (int idx = orderList.size() - 1; idx >= 0; --idx) {
        int curN = orderList[idx].first, curK = orderList[idx].second;
        if (curN == 0) {
            dp[curN][curK] = 1;
            continue;
        }
        if (curK == 0) {
            dp[curN][curK] = 0;
            continue;
        }

        int step = 1 << bitCount[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (twoPowerCount[i] + twoPowerCount[curN - i] == twoPowerCount[curN]) {
                dp[curN][curK] = ((long long)dp[curN][curK] + (long long)binomial(curN, i) * dp[curN - i][curK - 1] % modVal * curK) % modVal;
            }
        }
    }

    return dp[startN][startK];
}

int main() {
    readInt(n);
    readInt(k);
    readLL(modVal);

    fact[0] = 1;
    memset(visited, 0, sizeof(visited));
    bitCount[0] = -1;

    for (int i = 1; i <= 262150; ++i) {
        fact[i] = (long long)fact[i - 1] * i % modVal;
        bitCount[i] = bitCount[i >> 1] + 1;
        twoPowerCount[i] = twoPowerCount[i - 1] + countTrailingZeros(i);
    }

    invFact[262150] = modPow(fact[262150], modVal - 2);
    for (int i = 262149; i >= 1; --i) {
        invFact[i] = (long long)invFact[i + 1] * (i + 1) % modVal;
    }

    invFact[0] = invFact[1];

    if (n & 1) {
        cout << modPow(k, n) << '\n';
    } else {
        int ans = modPow(k, n);
        int result = iterativeSolve(n, k);
        cout << ((ans - result) % modVal + modVal) % modVal;
    }
}
